DROP TABLE IF EXISTS `kandidat_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kandidat_history` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kandidat_id` int NOT NULL,
  `admin_id` int DEFAULT NULL,
  `admin_nama` varchar(200) DEFAULT NULL,
  `action_type` enum('create','update','delete','status_change','dokumen','interview','komentar') NOT NULL,
  `field_name` varchar(100) DEFAULT NULL,
  `old_value` text,
  `new_value` text,
  `description` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `kandidat_id` (`kandidat_id`),
  KEY `admin_id` (`admin_id`),
  CONSTRAINT `kandidat_history_ibfk_1` FOREIGN KEY (`kandidat_id`) REFERENCES `kandidat_profil` (`id`) ON DELETE CASCADE,
  CONSTRAINT `kandidat_history_ibfk_2` FOREIGN KEY (`admin_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1678 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

