DROP TABLE IF EXISTS `kandidat_keluarga`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kandidat_keluarga` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kandidat_id` int NOT NULL,
  `hubungan` enum('Ayah','Ibu','Suami','Istri','Kakak','Adik','Lainnya') NOT NULL,
  `nama` varchar(200) DEFAULT NULL,
  `usia` int DEFAULT NULL,
  `pekerjaan` varchar(150) DEFAULT NULL,
  `penghasilan` varchar(50) DEFAULT NULL,
  `urutan` int DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `kandidat_id` (`kandidat_id`),
  CONSTRAINT `kandidat_keluarga_ibfk_1` FOREIGN KEY (`kandidat_id`) REFERENCES `kandidat_profil` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4615 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

