DROP TABLE IF EXISTS `kandidat_pendidikan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kandidat_pendidikan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kandidat_id` int NOT NULL,
  `jenjang` enum('SD','SMP','SMA/SMK','Perguruan Tinggi') NOT NULL,
  `nama_sekolah` varchar(200) DEFAULT NULL,
  `bulan_masuk` varchar(20) DEFAULT NULL,
  `tahun_masuk` year DEFAULT NULL,
  `bulan_lulus` varchar(20) DEFAULT NULL,
  `tahun_lulus` year DEFAULT NULL,
  `jurusan` varchar(150) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `kandidat_id` (`kandidat_id`),
  CONSTRAINT `kandidat_pendidikan_ibfk_1` FOREIGN KEY (`kandidat_id`) REFERENCES `kandidat_profil` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4688 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

