DROP TABLE IF EXISTS `kandidat_pengalaman_kerja`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kandidat_pengalaman_kerja` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kandidat_id` int NOT NULL,
  `nama_perusahaan` varchar(200) DEFAULT NULL,
  `alamat_perusahaan` text,
  `posisi` varchar(150) DEFAULT NULL,
  `bulan_masuk` varchar(20) DEFAULT NULL,
  `tahun_masuk` year DEFAULT NULL,
  `bulan_keluar` varchar(20) DEFAULT NULL,
  `tahun_keluar` year DEFAULT NULL,
  `masih_bekerja` tinyint(1) DEFAULT '0',
  `deskripsi_pekerjaan` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `kandidat_id` (`kandidat_id`),
  CONSTRAINT `kandidat_pengalaman_kerja_ibfk_1` FOREIGN KEY (`kandidat_id`) REFERENCES `kandidat_profil` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=727 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

