--
-- Table structure for table `kandidat_profil`
--

DROP TABLE IF EXISTS `kandidat_profil`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kandidat_profil` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `cabang_id` int DEFAULT NULL,
  `nama_katakana` varchar(200) DEFAULT NULL,
  `nama_romaji` varchar(200) DEFAULT NULL,
  `tempat_lahir` varchar(100) DEFAULT NULL,
  `tanggal_lahir` date DEFAULT NULL,
  `umur` int DEFAULT NULL,
  `jenis_kelamin` enum('Laki-laki','Perempuan') DEFAULT NULL,
  `status_pernikahan` enum('Menikah','Belum Menikah') DEFAULT NULL,
  `jumlah_anak` int DEFAULT '0',
  `agama` varchar(50) DEFAULT NULL,
  `tinggi_badan` int DEFAULT NULL,
  `berat_badan` int DEFAULT NULL,
  `golongan_darah` enum('A','B','AB','O','Tidak Tahu') DEFAULT NULL,
  `tangan_dominan` enum('Kanan','Kiri') DEFAULT NULL,
  `ukuran_baju` enum('S','M','L','XL','XXL','Lainnya') DEFAULT NULL,
  `lingkar_pinggang` decimal(5,1) DEFAULT NULL,
  `panjang_telapak_kaki` decimal(5,1) DEFAULT NULL,
  `sim_dimiliki` varchar(100) DEFAULT NULL,
  `nomor_hp` varchar(20) DEFAULT NULL,
  `email_kontak` varchar(100) DEFAULT NULL,
  `alamat_lengkap` text,
  `kontak_ortu_nama` varchar(200) DEFAULT NULL,
  `kontak_ortu_hp` varchar(20) DEFAULT NULL,
  `sudah_vaksin` tinyint(1) DEFAULT '0',
  `penglihatan_kanan` varchar(50) DEFAULT NULL,
  `penglihatan_kiri` varchar(50) DEFAULT NULL,
  `berkacamata` tinyint(1) DEFAULT '0',
  `lensa_kontak` tinyint(1) DEFAULT '0',
  `buta_warna` tinyint(1) DEFAULT '0',
  `kondisi_kesehatan` enum('Sehat','Tidak Sehat') DEFAULT 'Sehat',
  `riwayat_penyakit` text,
  `bertato` tinyint(1) DEFAULT '0',
  `merokok` tinyint(1) DEFAULT '0',
  `minum_alkohol` tinyint(1) DEFAULT '0',
  `intensitas_alkohol` varchar(100) DEFAULT NULL,
  `pernah_ke_jepang` tinyint(1) DEFAULT '0',
  `keluarga_di_jepang` tinyint(1) DEFAULT '0',
  `hubungan_keluarga_jepang` varchar(100) DEFAULT NULL,
  `status_kerabat_jepang` varchar(100) DEFAULT NULL,
  `kontak_keluarga_jepang` varchar(100) DEFAULT NULL,
  `kenalan_di_jepang` tinyint(1) DEFAULT '0',
  `kenalan_jepang_detail` text,
